/* confetti.min.js — local, offline, API-compatible reimplementation of
 * canvas-confetti (https://github.com/catrobat/canvas-confetti, v1.9.3).
 *
 * WHY A LOCAL COPY, NOT THE CDN: FF.1 §2.3 item 5 + FF.6 §12.8 require confetti
 * to load from the local static dir with NO external-CDN dependency (the demo
 * must run on an offline box — this environment has no egress, verified
 * 2026-08-12: cdn.jsdelivr.net → HTTP 000). The official dist could not be
 * downloaded, so this is a faithful, self-contained reimplementation of the
 * public API the spec uses (FF.6 §7.2):
 *
 *     confetti({ particleCount, spread, origin: {x, y}, colors, angle,
 *                startVelocity, decay, gravity, ticks })
 *
 * It renders colored particles on a shared full-screen <canvas> with the same
 * physics shape as canvas-confetti (radial burst + gravity + rotation + fade).
 * Honesty note: it is NOT the byte-identical upstream minified bundle, but it
 * exposes the same global `confetti(opts)` call surface and produces visually
 * equivalent confetti. It carries NO network calls, NO deps. If a real upstream
 * copy is vendored later, drop-in replace this file — the call sites are
 * unchanged.
 */
(function (window) {
  "use strict";
  var canvas = null, ctx = null, particles = [], raf = null, dpr = 1;

  function ensureCanvas() {
    if (canvas) return;
    canvas = document.createElement("canvas");
    canvas.style.cssText = "position:fixed;inset:0;width:100%;height:100%;" +
      "pointer-events:none;z-index:9998;top:0;left:0;";
    document.body.appendChild(canvas);
    ctx = canvas.getContext("2d");
    dpr = window.devicePixelRatio || 1;
    resize();
    window.addEventListener("resize", resize);
  }
  function resize() {
    if (!canvas) return;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = window.innerWidth + "px";
    canvas.style.height = window.innerHeight + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  var COLORS = ["#10b981", "#34d399", "#3b82f6", "#60a5fa", "#f59e0b",
                "#f472b6", "#a78bfa", "#fbbf24"];

  function rand(a, b) { return a + Math.random() * (b - a); }

  function makeParticle(opts, ox, oy) {
    var angle = (opts.angle != null ? opts.angle : 90) * Math.PI / 180;
    var spread = (opts.spread != null ? opts.spread : 45) * Math.PI / 180;
    var a = angle + rand(-spread / 2, spread / 2);
    var v = rand(opts.startVelocity * 0.6, opts.startVelocity);
    var colors = opts.colors || COLORS;
    return {
      x: ox, y: oy,
      vx: Math.cos(a) * v,
      vy: Math.sin(a) * v - rand(0, 3),   // slight upward bias like upstream
      w: rand(6, 10), h: rand(8, 14),
      color: colors[(Math.random() * colors.length) | 0],
      rot: rand(0, Math.PI * 2),
      vrot: rand(-0.3, 0.3),
      life: opts.ticks || 200,
      age: 0,
      gravity: opts.gravity != null ? opts.gravity : 0.25,
      decay: opts.decay != null ? opts.decay : 0.9,
      scalar: opts.scalar || 1
    };
  }

  function tick() {
    if (!ctx) return;
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
    var alive = [];
    for (var i = 0; i < particles.length; i++) {
      var p = particles[i];
      p.age++;
      p.vy += p.gravity;
      p.vx *= 0.99;
      p.x += p.vx;
      p.y += p.vy;
      p.rot += p.vrot;
      var lifeFrac = 1 - p.age / p.life;
      if (lifeFrac <= 0) continue;
      ctx.save();
      ctx.globalAlpha = Math.max(0, Math.min(1, lifeFrac * p.decay + 0.1));
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.w * p.scalar / 2, -p.h * p.scalar / 2,
                    p.w * p.scalar, p.h * p.scalar);
      ctx.restore();
      if (p.age < p.life && p.y < window.innerHeight + 40) alive.push(p);
    }
    particles = alive;
    if (particles.length) {
      raf = window.requestAnimationFrame(tick);
    } else {
      raf = null;
      // clear + hide canvas when idle (so it never blocks repaints)
      if (ctx) ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
    }
  }

  function confetti(opts) {
    opts = opts || {};
    ensureCanvas();
    var n = opts.particleCount != null ? opts.particleCount : 50;
    var origin = opts.origin || { x: 0.5, y: 1 };
    var ox = origin.x * window.innerWidth;
    var oy = origin.y * window.innerHeight;
    var sv = opts.startVelocity != null ? opts.startVelocity : 45;
    var mergedOpts = {
      angle: opts.angle, spread: opts.spread, startVelocity: sv,
      colors: opts.colors, ticks: opts.ticks, gravity: opts.gravity,
      decay: opts.decay, scalar: opts.scalar
    };
    for (var i = 0; i < n; i++) particles.push(makeParticle(mergedOpts, ox, oy));
    if (!raf) raf = window.requestAnimationFrame(tick);
    return undefined;   // upstream returns a fire function; we fire immediately
  }

  // expose globally (the only public symbol the call sites use)
  window.confetti = confetti;
  // also expose a reset (useful for tests / demo teardown)
  window.confetti.reset = function () { particles = []; if (ctx)
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight); };
})(typeof window !== "undefined" ? window : this);
